conditions.raw:
OR = {
	AND = {
		is_subject = yes
		NOT = { OVERLORD = { is_in_faction_with = var:global.zin_eindil_host } }
	}
	AND = {
		is_in_faction = yes
		NOT = { is_in_faction_with = var:global.zin_eindil_host }
	}
}

NOT = { has_country_flag = zin_concord_charter_recent }
OR = {
	check_variable = { zin_concord_petition_code = 0 }
	AND = {
		check_variable = { zin_concord_petition_code = 1 }
		OVERLORD = {
			has_country_flag = zin_aenor_golden_charters_open
			check_variable = { zin_court_corruption > 39 }
			OR = {
				zin_aenor_king_alive = yes
				zin_aenor_ruled_by_court = yes
			}
		}
	}
	AND = {
		check_variable = { zin_concord_petition_code = 2 }
		has_global_flag = zin_lost_cause_shield
	}
	AND = {
		check_variable = { zin_concord_petition_code = 3 }
		OVERLORD = {
			OR = {
				has_country_flag = zin_aenor_free_charters_open
				zin_aenor_ruled_by_dominions = yes
				zin_aenor_ruled_by_host = yes
			}
		}
	}
}

any_country = {
	zin_aenor_is_realm = yes
	any_controlled_state = { zin_is_site_parim = yes }
	NOT = { zin_aenor_ruled_by_faithful = yes }
}

is_in_faction = no
any_country = {
	has_country_flag = zin_aenor_free_dominion
	is_faction_leader = yes
}

OVERLORD = {
	OR = {
		zin_aenor_ruled_by_host = yes
		zin_aenor_ruled_by_captains = yes
	}
}

effects.raw:
# zin_arg_camp and zin_arg_value stay set for zin_aenor_add_camp_support.
if = {
	limit = {
		has_global_flag = zin_golden_king_dead
		NOT = { has_global_flag = zin_eindil_crowned }
	}
	if = {
		limit = {
			is_subject = yes
			OVERLORD = { zin_aenor_is_realm = yes }
		}
		OVERLORD = { zin_aenor_add_camp_support = yes }
	}
	else = {
		zin_aenor_event_for_parim = yes
		if = {
			limit = { has_event_target = zin_aenor_parim_realm }
			event_target:zin_aenor_parim_realm = { zin_aenor_add_camp_support = yes }
		}
	}
}

random_country = {
	limit = {
		has_country_flag = zin_aenor_free_dominion
		is_faction_leader = yes
	}
	add_to_faction = ROOT
}
